Migrate this XCTest class to Swift Testing. Keep its behavior identical.

```swift
import XCTest
@testable import Shop

final class CartTests: XCTestCase {
    var cart: Cart!

    override func setUp() {
        continueAfterFailure = false
        cart = Cart()
    }

    override func tearDown() {
        PriceCache.shared.reset()
    }

    func testTotalIncludesTax() throws {
        try XCTSkipUnless(ProcessInfo.processInfo.isOperatingSystemAtLeast(.init(majorVersion: 26, minorVersion: 0, patchVersion: 0)))
        cart.add(Item(price: 10))
        XCTAssertEqual(cart.total, 10.8, accuracy: 0.001)
        XCTAssertEqual(cart.items.count, 1)
    }

    func testCheckoutCallsBack() {
        let exp = expectation(description: "checkout")
        cart.checkout { result in
            XCTAssertNotNil(try? result.get())
            exp.fulfill()
        }
        wait(for: [exp], timeout: 5)
    }
}
```

